import{_ as s,l as o,o as e,c as l,v as t,p as i,x as T,d as n,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const N=JSON.parse('{"title":"DNS 缓存与 TTL","description":"","frontmatter":{"title":"DNS 缓存与 TTL","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dns-cache-ttl.md","filePath":"cs/dns-cache-ttl.md","lastUpdated":1789023840000}'),p={name:"cs/dns-cache-ttl.md"};function h(D,a,L,S,_,u){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="dns-缓存与-ttl" tabindex="-1">DNS 缓存与 TTL <a class="header-anchor" href="#dns-缓存与-ttl" aria-label="Permalink to &quot;DNS 缓存与 TTL&quot;">​</a></h1><div class="epigraph"><p>每条记录带着 TTL，解析器与主机按它缓存；TTL 是延迟与一致性的旋钮，不是密码学保证。</p><footer>—— 据 RFC 1034 / 1035；RFC 2308 否定缓存；Kurose and Ross DNS 节整理</footer></div><p>主干<a href="/cs/dns">DNS</a>、<a href="/cs/dns-recursive">递归</a>、<a href="/cs/dns-rr">记录</a> 已给查询链。<a href="/cs/serialization-protobuf">上一课</a> 结束 Web 协议。缺口是<strong>缓存时间</strong>：正缓存、负缓存、过短打根、过长难切换。本课不把 DNSSEC 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每次 URL 都跑迭代会把根打爆，也把 RTT 加进网页。TTL：权威说这份 A 记录能记多久。CDN 用短 TTL 做故障切换；长 TTL 抗 DDoS、减延迟。负缓存（NXDOMAIN）防止缓存穿透。TTL=0 几乎禁用缓存。与 HTTP Cache-Control 同类旋钮，名字空间不同。任播根不靠 TTL 切流量。</p><p>不要把 TTL 写成证书有效期。</p><p><span class="marginnote">RFC 2308。最小 TTL 与 TTL 上限是解析器政策。本课不把每种 RR 的 TTL 策略写完。</span></p><h3 id="ttl-不是证书期" tabindex="-1">TTL 不是证书期 <a class="header-anchor" href="#ttl-不是证书期" aria-label="Permalink to &quot;TTL 不是证书期&quot;">​</a></h3><p>正负缓存都遵它。短则灵活费查询，长则切得慢。公共解析器让 Geo 变钝。TTL=1s 会打爆权威。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：权威 → 递归缓存 → stub。对照 BGP 收敛：DNS 切换受 TTL 下界约束，常比 BGP 慢或快取决于值。测：看应答里的剩余 TTL。</p>',11)),(e(),i(c,null,{default:T(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20AUTH%5B%22%E6%9D%83%E5%A8%81%20TTL%22%5D%20--%3E%20REC%5B%22%E9%80%92%E5%BD%92%E7%BC%93%E5%AD%98%22%5D%0A%20%20REC%20--%3E%20STUB%5B%22%E4%B8%BB%E6%9C%BA%E7%BC%93%E5%AD%98%22%5D%0A%20%20NEG%5B%22NXDOMAIN%22%5D%20--%3E%20NC%5B%22%E8%B4%9F%E7%BC%93%E5%AD%98%22%5D%0A"})]),fallback:T(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Cookie 会话不替代 DNS 缓存。GeoDNS 下一课用同一 TTL 机制发不同答案。H3 的 HTTPS RR 也有 TTL。过期后要重新查询，无线贵。劫持缓存（没有 DNSSEC）是安全课对象。</p><p>负载均衡用短 TTL 轮询多 A 记录，与 ECMP 不同：在解析器，不在包哈希。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 prefetch 的全部。DNSSEC 是下一课。后课默认：TTL 管 DNS 缓存寿命；切换速度不快于 TTL。</p><p>把所有记录 TTL 设 1 秒会把解析器变成权威的 DDoS 放大器。</p><p>上一课留下的缺口在本课收口；「DNS 缓存与 TTL」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/dnssec">DNSSEC</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>正/负缓存都遵 TTL。</li><li>短 TTL 灵活、费查询；长 TTL 稳、切得慢。</li><li>与 HTTP 缓存同构不同层。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 1034/1035；RFC 2308。</li></ul>',10))])}const f=s(p,[["render",h]]);export{N as __pageData,f as default};
